  const pageId = String(body.pageId || '').trim();
  if (!/^[0-9a-f]{8}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{12}$/i.test(pageId)) {
    errors.push('pageId must be a Notion page UUID');
  }
  output.pageId = pageId.replace(/-/g, '').toLowerCase();
