  json: {
    ...request,
    repository: request.repository || 'notion',
    commit: String(blocks[0]?.last_edited_time || request.receivedAt),
    documents,
    notion: { blockCount: blocks.length, truncated: Boolean(response.has_more) },
  },
}];

