  const vector = data[i].embedding;
  if (!Array.isArray(vector) || vector.length !== dimensions) {
    throw new Error(`Embedding ${i} has an unexpected shape`);
  }
  return {
    id: chunk.id,
    vector,
    payload: {
      source: batch.source,
      repository: batch.repository,
      ref: batch.ref,
      commit: batch.commit,
      requestId: batch.requestId,
      path: chunk.path,
      title: chunk.title,
      heading: chunk.heading,
      chunkIndex: chunk.chunkIndex,
      tags: chunk.tags,
      text: chunk.text,
      contentHash: chunk.contentHash,
      docHash: chunk.docHash,
      syncedAt,
    },
  };
});

return [{ json: { points, dimensions, model: response.model || null, stampedAtMs: Date.now() } }];

// Function: Synthesize RAG Context & Metadata
// Assembles a token-budgeted context window (change set, updated chunks, semantic
// neighbours and taxonomy reference) plus a lightweight knowledge graph.

