  const out = [];
  let used = 0;
  let truncated = false;
  for (const block of blocks) {
    if (used + block.length > budget) {
      const remaining = budget - used;
      if (remaining > 200) out.push(`${block.slice(0, remaining)}\n…[truncated]`);
      truncated = true;
      break;
    }
    out.push(block);
    used += block.length;
  }
  return { text: out.join('\n\n'), truncated };
}

